-- 006 — avisos da edição + entrega multicanal + canal de dúvidas
-- (spec 033 US2/US3, FR-003/FR-004/FR-010). Substitui o grupo do zap:
-- o aviso nasce aqui, vira notificação in-app, e-mail e (com opt-in)
-- WhatsApp individual. Cada entrega é uma linha em deliveries; a unique
-- (announcementId, memberId, channel) é a idempotência — refazer o fan-out
-- ou rodar o worker de novo nunca duplica envio.

CREATE TABLE announcements (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id"),
  "audience" TEXT NOT NULL CHECK ("audience" IN ('todos','aprovados','presentes','time')),
  "teamId" INTEGER REFERENCES teams("id"),
  "title" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "createdBy" INTEGER REFERENCES members("id"),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  CHECK (("audience" = 'time') = ("teamId" IS NOT NULL))
);
CREATE INDEX idx_announcements_hackathon ON announcements ("hackathonId", "id" DESC);

-- status: queued → sent | failed | skipped. 'failed' com attempts < 3 e
-- nextAttemptAt vencido volta pro worker (backoff); claimedAt é a trava do
-- worker (dois processos não pegam a mesma linha).
CREATE TABLE deliveries (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "announcementId" INTEGER NOT NULL REFERENCES announcements("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "channel" TEXT NOT NULL CHECK ("channel" IN ('inapp','email','whatsapp')),
  "status" TEXT NOT NULL DEFAULT 'queued' CHECK ("status" IN ('queued','sent','failed','skipped')),
  "error" TEXT,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "nextAttemptAt" TEXT,
  "claimedAt" TEXT,
  "sentAt" TEXT,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  UNIQUE ("announcementId", "memberId", "channel")
);
CREATE INDEX idx_deliveries_pending ON deliveries ("status", "nextAttemptAt");
CREATE INDEX idx_deliveries_member ON deliveries ("memberId");

-- "não lido" do aviso na página da edição (independe da notificação do sino)
CREATE TABLE announcement_reads (
  "announcementId" INTEGER NOT NULL REFERENCES announcements("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "readAt" TEXT NOT NULL DEFAULT sqlite_now(),
  PRIMARY KEY ("announcementId", "memberId")
);

-- FR-010: telefone + opt-in de WhatsApp separados do e-mail; bounce de
-- e-mail marca o contato e o worker para de insistir.
ALTER TABLE members ADD COLUMN "phone" TEXT;
ALTER TABLE members ADD COLUMN "whatsappOptIn" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE members ADD COLUMN "whatsappOptInAt" TEXT;
ALTER TABLE members ADD COLUMN "emailBouncedAt" TEXT;

CREATE TABLE questions (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hackathonId" TEXT NOT NULL REFERENCES hackathons("id"),
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "body" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now(),
  "resolvedAt" TEXT,
  "resolvedBy" INTEGER REFERENCES members("id")
);
CREATE INDEX idx_questions_hackathon ON questions ("hackathonId", "resolvedAt", "id" DESC);

CREATE TABLE answers (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "questionId" INTEGER NOT NULL REFERENCES questions("id") ON DELETE CASCADE,
  "memberId" INTEGER NOT NULL REFERENCES members("id"),
  "body" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now()
);
CREATE INDEX idx_answers_question ON answers ("questionId", "id");
